// Get raw Telegram update from previous node
const update = $input.first().json.body;

// 1. Extract chat_id and user text
const chatId = update.message?.chat?.id;
const rawText = (update.message?.text || "").trim();

// We'll work in lowercase for matching styles, but keep original for city.
const lower = rawText.toLowerCase();

// 2. Extract style
// Add/adjust this list to whatever styles you support.
const STYLE_KEYWORDS = [
  "casual",
  "sport",
  "sports",
  "business",
  "formal",
  "elegant",
  "street",
  "outdoor",
  "smart casual",
  "business casual"
];

// We'll pick the first style word that appears in the text.
let style = null;
for (const s of STYLE_KEYWORDS) {
  if (lower.includes(s)) {
    style = s;
    break;
  }
}
if (!style) {
  style = "casual"; // fallback default
}

// 4. Extract city
// Strategy:
//   - remove the duration phrase
//   - remove detected style word
//   - what's left (trimmed) is assumed to be location/city string
//
// Caveat: We want the *original* casing for city, not lowercase.
let workingText = rawText;

// remove style word
if (style) {
  // escape style for regex
  const esc = style.replace(/[.*+?^${}()|[\]\\]/g, "\\$&");
  workingText = workingText.replace(new RegExp(esc, "i"), "");
}

// also remove leftover "h", "hour", etc next to the number if not caught
workingText = workingText
  .replace(/\b(h|hr|hrs|hour|hours)\b/i, "")
  .replace(/\s+/g, " ") // collapse multiple spaces
  .trim();

// After cleanup, workingText should mostly be city / location.
// If it's now empty, you can fallback to a default city (optional).
let city = workingText;
if (!city) {
  city = "Berlin"; // <- set your default city here
}

// 5. Build clean structured result
const result = {
  chat_id: chatId,
  style: style,
  city: city,
  original_text: rawText
};

// Return one item so next nodes can use {{$json.field}}
return [{ json: result }];
